<!-- 文件作用：呈现可辨识的游戏图标及可搜索的完整游戏目录，各页面共用同一选择状态。 -->
<template>
  <view class="game-picker">
    <view v-if="catalog" class="game-heading"><text>选择游戏</text><button class="game-catalog-trigger" @click="openCatalog">全部 {{ state.games.length }} 款 <Icon name="arrow" :size="12" /></button></view>
    <scroll-view class="games-scroll" scroll-x :show-scrollbar="false" :scroll-left="gameScrollLeft"><view class="games-list"><button v-for="item in state.games" :key="item.id" :id="'game-' + item.id" class="game-choice" :class="{chosen: state.gameId === item.id}" @click="selectGame(item.id)"><view class="game-image"><image class="game-cover" :src="assetUrl(item.icon_url || item.cover_url || item.covers?.[0])" mode="aspectFill"/><view v-if="state.gameId === item.id" class="game-check"><Icon name="check" :size="10" color="#07170d" /></view></view><text>{{ item.short_name || item.name }}</text></button></view></scroll-view>
    <view v-if="catalogOpen" class="catalog-mask" @click="catalogOpen=false"><view class="catalog-sheet" @click.stop><view class="catalog-heading"><view><text class="catalog-title">全部游戏</text><view class="catalog-subtitle">找到你的下一场对局</view></view><button class="catalog-close" @click="catalogOpen=false"><Icon name="close" :size="23" /></button></view><view class="catalog-search"><Icon name="search" :size="18"/><input v-model="search" class="catalog-search-input" placeholder="搜索游戏名称"/></view><scroll-view scroll-y class="catalog-scroll"><view class="catalog-grid"><button v-for="item in filteredGames" :key="item.id" class="catalog-game" :class="{selected:state.gameId===item.id}" @click="chooseFromCatalog(item.id)"><image class="catalog-game-image" :src="assetUrl(item.icon_url || item.cover_url)" mode="aspectFill"/><text>{{ item.name }}</text><view v-if="state.gameId===item.id" class="selected-text">当前游戏</view></button></view><view v-if="!filteredGames.length" class="catalog-empty">没有找到这个游戏</view><view class="catalog-note">热门游戏精选 · 显示顺序由平台配置</view></scroll-view></view></view>
  </view>
</template>
<script setup>
import { computed, ref } from 'vue'
import { state, selectGame } from '../lib/store'
import { assetUrl } from '../lib/format'
import Icon from './Icon.vue'
defineProps({ catalog: Boolean })
const catalogOpen = ref(false), search = ref('')
// 前两项保留在可见区，默认三角洲选中时仍展示热门首排，避免原生滚动把它强制置顶。
const gameScrollLeft = computed(() => Math.max(0,state.games.findIndex(item => item.id===state.gameId)-2)*73)
const filteredGames = computed(() => state.games.filter(item => ((item.name || '') + (item.short_name || '') + item.id).toLowerCase().includes(search.value.trim().toLowerCase())))
/** 打开完整目录并清除上次筛选。 */
function openCatalog() { search.value = ''; catalogOpen.value = true }
/** 选择目录中的游戏后回到当前业务页面。 */
function chooseFromCatalog(id) { selectGame(id); catalogOpen.value = false }
</script>
<style scoped>
.game-heading{display:flex;align-items:center;justify-content:space-between;padding:4px 12px 0;font-size:15px;font-weight:750}.game-catalog-trigger{margin:0;display:flex;align-items:center;gap:4px;min-height:30px;padding:0;background:none;border:0;color:#bdc6c0;font-size:11px;font-weight:400;line-height:30px}.games-scroll{width:100%;white-space:nowrap;margin:4px 0}.games-list{display:flex;gap:13px;padding:2px 12px 4px}.game-choice{flex-shrink:0;text-align:center;width:60px;color:#c4c9c6;font-size:12px;cursor:pointer;background:none;padding:0;line-height:1.5;border:0;border-radius:0}.game-image{width:54px;height:54px;border-radius:10px;overflow:hidden;border:1px solid #ffffff44;position:relative;margin:0 auto 5px}.game-cover{width:100%;height:100%}.game-choice.chosen{color:var(--accent);font-weight:750}.chosen .game-image{border:2px solid var(--accent)}.game-check{position:absolute;right:2px;top:2px;width:14px;height:14px;background:var(--accent);border-radius:50%;display:flex;align-items:center;justify-content:center}.catalog-mask{position:fixed;inset:0;background:#000b;z-index:100;display:flex;align-items:flex-end;justify-content:center}.catalog-sheet{background:var(--surface);border:1px solid #ffffff20;border-radius:20px 20px 0 0;width:100%;max-width:600px;padding:20px 16px calc(20px + env(safe-area-inset-bottom))}.catalog-heading{display:flex;align-items:center;justify-content:space-between}.catalog-title{font-size:21px;font-weight:750}.catalog-subtitle{font-size:12px;color:#a5b1a9;margin-top:3px}.catalog-close{margin:0;background:none;border:0;color:var(--text);padding:8px;line-height:26px}.catalog-search{display:flex;align-items:center;gap:8px;background:#ffffff08;border:1px solid #ffffff20;padding:10px 12px;border-radius:10px;margin:18px 0;color:#9dab9f}.catalog-search-input{flex:1;font-size:14px}.catalog-scroll{max-height:58vh;height:390px}.catalog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px 7px}.catalog-game{margin:0;width:100%;display:flex;align-items:center;flex-direction:column;gap:7px;padding:8px 1px;border:1px solid transparent;border-radius:10px;color:var(--text);background:transparent;line-height:1.4;font-size:11px}.catalog-game-image{width:57px;height:57px;border-radius:12px;border:1px solid #ffffff26}.catalog-game.selected{border-color:var(--accent);color:var(--accent)}.selected-text{font-size:10px;color:var(--accent)}.catalog-empty{text-align:center;padding:32px;color:#adbbb2}.catalog-note{font-size:10px;text-align:center;padding:20px 0 4px;color:#97a69d}@media(max-width:350px){.games-list{gap:11px;padding-left:10px;padding-right:10px}.game-choice{width:51px;font-size:11px}.game-image{width:51px;height:51px}}
</style>
